// In runOnceForEachItem mode return a single item, not an array
const email = ($json && typeof $json === 'object') ? $json : {};

let fromAddr = '';
if (email.From && typeof email.From === 'string') {
  const m = email.From.match(/<([^>]+)>/);
  fromAddr = m ? m[1] : email.From;
}

const subject = String(email.Subject || email.subject || '');
const body = String(email.textPlain || email.body || email.snippet || '');

// 1) From display name
let customerName = '';
if (email.From && typeof email.From === 'string') {
  const stripped = email.From.replace(/<[^>]+>/, '').trim().replace(/^["']|["']$/g, '');
  if (stripped) {
    const parts = stripped.split(/\s+/).filter(Boolean);
    if (parts.length >= 2) {
      customerName = parts[0];
    } else if (parts.length === 1 && /^[A-Za-z][A-Za-z'.-]*$/.test(parts[0]) && parts[0].length >= 2) {
      customerName = parts[0];
    }
  }
}

// 2) Email body signature
if (!customerName) {
  const sigPatterns = [
    /--\s*\n([\s\S]*?)$/i,
    /__\s*\n([\s\S]*?)$/i,
    /^-{3,}\s*\n([\s\S]*?)$/m,
    /(?:best regards|kind regards|regards|cheers|sincerely|thanks(?: so much)?|thank you),?\s*\n+([A-Za-z][A-Za-z' .-]{1,40})\b/i
  ];
  for (const pat of sigPatterns) {
    const m = body.match(pat);
    if (m && m[1]) {
      const candidate = m[1].trim().split(/\s+/)[0];
      if (candidate && /^[A-Za-z][A-Za-z'.-]*$/.test(candidate) && candidate.length >= 2) {
        customerName = candidate;
        break;
      }
    }
  }
}

// 3) Local-part
if (!customerName) {
  const local = fromAddr.split('@')[0] || '';
  const part = local.split(/[._-]/)[0] || '';
  if (part && /^[A-Za-z][A-Za-z]*$/.test(part) && part.length >= 2) {
    customerName = part;
  } else {
    customerName = 'there';
  }
}

if (customerName && customerName !== 'there') {
  customerName = customerName.charAt(0).toUpperCase() + customerName.slice(1).toLowerCase();
}

const promptLines = [];
promptLines.push('You are a triage agent for Gadget & More Electronics customer support.');
promptLines.push('Decide if the email is about one of the topics in the knowledge base below.');
promptLines.push('Reply ONLY with a JSON object of this exact shape (no prose, no markdown fences):');
promptLines.push('{"in_scope": <bool>, "category": "<shipping|returns|warranty|billing|subscriptions|privacy|gift-cards|pricing|general>", "draft_reply": "<string>", "customer_name": "<string>", "confidence": "<high|med|low>", "reasoning": "<one short sentence>"}');
promptLines.push('');
promptLines.push('Brand voice for the draft_reply:');
promptLines.push('- Friendly, tech-savvy, casual — like a knowledgeable friend at a gadget shop.');
promptLines.push('- Use contractions (we\'re, you\'ll, it\'s). Keep it warm but not overly chatty.');
promptLines.push('- Sprinkle in light technical context when relevant (model numbers, spec terms) without being jargon-heavy.');
promptLines.push('- Avoid stiff corporate phrases ("Dear valued customer", "Please be advised"). Never use exclamation marks unless genuinely warranted.');
promptLines.push('');
promptLines.push('Confidence scoring — set the "confidence" field based on how well the email matches the knowledge base:');
promptLines.push('- "high" = the question is clearly covered by the knowledge base and you can answer it definitively with the chunks you have.');
promptLines.push('- "med"  = the question is related to a topic in the knowledge base but the exact answer is partial / requires some inference, OR you needed to combine multiple KB chunks.');
promptLines.push('- "low"  = the question is outside the knowledge base, the KB is empty, OR you had to guess. If in_scope is false, confidence should be "low".');
promptLines.push('');
promptLines.push('Rules:');
promptLines.push('- in_scope = true only if the question matches a topic in the knowledge base.');
promptLines.push('- draft_reply must be 3-6 sentences in the brand voice, using the relevant KB chunk.');
promptLines.push('- Address the customer by their first name (provided below) — e.g. "Hey Alex," or "Hi Alex,". If the name looks like a system/local-part (no spaces, weird chars), fall back to "Hi there,".');
promptLines.push('- If in_scope is false, draft_reply must STILL be a polite acknowledgment that the question is outside the available knowledge base and that the team will research and get back within 24 hours, in the same brand voice. Set confidence to "low" in this case.');
promptLines.push('- Always end with the sign-off: "Thanks,\nGadget & More Support"');
promptLines.push('');
promptLines.push('Customer first name: ' + customerName);
promptLines.push('');
promptLines.push('Knowledge base:');
const systemPrompt = promptLines.join('\n');

const userPrompt = 'From: ' + fromAddr + '\nSubject: ' + subject + '\n\n' + body;

return {
  json: {
    systemPrompt: systemPrompt,
    userPrompt: userPrompt,
    threadId: String(email.threadId || ''),
    messageId: String(email.id || ''),
    from: fromAddr,
    subject: subject,
    customerName: customerName
  }
};

// runOnceForEachItem requires a SINGLE object ({json: ...}), not an array.
const raw = String($json.text || $json.output || '');
let parsed = { in_scope: false, category: 'general', draft_reply: '', customer_name: '', confidence: 'low', reasoning: 'no parse' };
try {
  const match = raw.match(/\{[\s\S]*\}/);
  if (match) parsed = JSON.parse(match[0]);
} catch (e) {
  parsed.reasoning = 'parse error: ' + e.message;
}
// Normalize confidence to one of high/med/low
let conf = String(parsed.confidence || '').toLowerCase().trim();
if (conf !== 'high' && conf !== 'med' && conf !== 'low') {
  conf = parsed.in_scope === true ? 'med' : 'low';
}
const bp = $('Build LLM prompt').item.json;
return {
  json: {
    in_scope: parsed.in_scope === true,
    category: String(parsed.category || 'general'),
    draft_reply: String(parsed.draft_reply || ''),
    customer_name: String(parsed.customer_name || bp.customerName || ''),
    confidence: conf,
    reasoning: String(parsed.reasoning || ''),
    threadId: String(bp.threadId || ''),
    from: String(bp.from || ''),
    subject: String(bp.subject || '')
  }
};
